insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-bmp-note-101','Pharmacy','Diploma in Pharmacy','note','free',701,'{"title":"Biochemistry: Biomolecules and Enzymes","english":"Biochemistry studies the chemical substances and reactions in living organisms. Carbohydrates are major energy sources; lipids store energy and form cell membranes; proteins provide structure and perform functions such as transport and catalysis; nucleic acids store and transmit genetic information. Enzymes are biological catalysts that increase reaction rates without being consumed. Enzyme activity is affected by temperature, pH, substrate concentration and inhibitors.","nepali":"Biochemistry ले जीवित शरीरमा रहेका रासायनिक पदार्थ र प्रतिक्रियाको अध्ययन गर्छ। Carbohydrate ऊर्जा स्रोत हो; lipid ले ऊर्जा सञ्चय र cell membrane निर्माण गर्छ; protein ले संरचना तथा transport र catalysis जस्ता काम गर्छ; nucleic acid ले genetic information राख्छ र सार्छ। Enzyme जैविक catalyst हो, जसले आफैँ खर्च नभई reaction छिटो गराउँछ। तापक्रम, pH, substrate concentration र inhibitor ले enzyme activity असर गर्छन्।"}'::jsonb,true),
('dph-bmp-note-102','Pharmacy','Diploma in Pharmacy','note','free',702,'{"title":"Metabolism, Blood Glucose and Clinical Biochemistry","english":"Metabolism includes catabolism, which breaks molecules down and releases energy, and anabolism, which builds molecules and uses energy. Glucose is an important fuel; insulin generally lowers blood glucose by promoting uptake and storage, while glucagon raises it by stimulating hepatic glucose output. Clinical biochemistry measures substances such as glucose, urea, creatinine, bilirubin, enzymes and electrolytes to help assess organ function and disease. Results must be interpreted with clinical context and reference intervals.","nepali":"Metabolism मा catabolism (अणु टुक्र्याएर ऊर्जा निकाल्ने) र anabolism (अणु बनाउने र ऊर्जा प्रयोग गर्ने) पर्छन्। Glucose महत्त्वपूर्ण ऊर्जा स्रोत हो; insulin ले glucose uptake र storage बढाएर सामान्यतया blood glucose घटाउँछ, जबकि glucagon ले liver बाट glucose उत्पादन बढाएर glucose बढाउँछ। Clinical biochemistry मा glucose, urea, creatinine, bilirubin, enzyme र electrolyte जस्ता पदार्थ मापन गरी अंगको कार्य र रोग मूल्याङ्कन गर्न मद्दत गरिन्छ। नतिजा clinical अवस्था र reference interval सँगै व्याख्या गर्नुपर्छ।"}'::jsonb,true),
('dph-bmp-note-103','Pharmacy','Diploma in Pharmacy','note','free',703,'{"title":"Microbiology: Microorganisms and Basic Classification","english":"Microbiology studies microorganisms. Important groups include bacteria, viruses, fungi, protozoa and microscopic algae. Bacteria are prokaryotic cells; fungi are eukaryotic organisms; viruses are acellular infectious agents that replicate only inside suitable host cells. Microorganisms may be useful in food production, biotechnology and medicine, or may cause infection. Correct identification, specimen handling and laboratory biosafety are essential.","nepali":"Microbiology ले सूक्ष्मजीवको अध्ययन गर्छ। मुख्य समूहमा bacteria, virus, fungi, protozoa र microscopic algae पर्छन्। Bacteria prokaryotic cell हुन्; fungi eukaryotic organism हुन्; virus कोशिकाविहीन infectious agent हो र उपयुक्त host cell भित्र मात्र वृद्धि/replication गर्छ। सूक्ष्मजीव खाना उत्पादन, biotechnology र औषधिमा उपयोगी हुन सक्छन् वा संक्रमण गराउन सक्छन्। सही पहिचान, specimen handling र laboratory biosafety आवश्यक हुन्छ।"}'::jsonb,true),
('dph-bmp-note-104','Pharmacy','Diploma in Pharmacy','note','free',704,'{"title":"Sterilization, Disinfection and Infection Control","english":"Sterilization destroys or removes all forms of microbial life, including bacterial spores, when a validated process is correctly used. Disinfection reduces or eliminates many pathogenic microorganisms on inanimate objects but may not destroy spores. Common methods include moist heat, dry heat, filtration, radiation and suitable chemical agents. Select a method according to the material and intended use; monitor processes with physical, chemical and biological indicators as appropriate. Hand hygiene, personal protective equipment and safe waste handling reduce infection risk.","nepali":"Sterilization ले मान्य प्रक्रिया सही रूपमा प्रयोग गर्दा bacterial spore सहित सबै प्रकारका microbial life नष्ट वा हटाउँछ। Disinfection ले निर्जीव वस्तुमा रहेका धेरै रोगकारक सूक्ष्मजीव घटाउँछ वा नष्ट गर्छ तर spore नष्ट नहुन सक्छ। Moist heat, dry heat, filtration, radiation र उपयुक्त chemical agent सामान्य विधि हुन्। वस्तुको प्रकृति र प्रयोगअनुसार विधि छान्नुपर्छ; आवश्यकताअनुसार physical, chemical र biological indicator बाट प्रक्रिया जाँचिन्छ। Hand hygiene, PPE र सुरक्षित फोहोर व्यवस्थापनले संक्रमण जोखिम घटाउँछ।"}'::jsonb,true),
('dph-bmp-note-105','Pharmacy','Diploma in Pharmacy','note','free',705,'{"title":"Pathology: Cell Injury, Inflammation and Common Laboratory Specimens","english":"Pathology studies disease, including its causes, mechanisms and structural or functional changes. Cell injury may be reversible or progress to cell death. Inflammation is a protective response to tissue injury or infection and commonly involves redness, heat, swelling, pain and loss of function. Common specimens include blood, urine, stool and swabs. Correct patient identification, appropriate collection container, labeling, timely transport and infection precautions help maintain specimen quality and patient safety.","nepali":"Pathology ले रोगका कारण, विकास प्रक्रिया तथा संरचनात्मक वा कार्यात्मक परिवर्तनको अध्ययन गर्छ। Cell injury उल्टिन सक्ने (reversible) वा cell death सम्म पुग्न सक्छ। Inflammation tissue injury वा infection प्रति शरीरको सुरक्षात्मक प्रतिक्रिया हो; यसमा redness, heat, swelling, pain र loss of function देखिन सक्छ। सामान्य specimen मा blood, urine, stool र swab पर्छन्। सही बिरामी पहिचान, उपयुक्त container, labeling, समयमै transport र infection precaution ले specimen को गुणस्तर तथा बिरामीको सुरक्षा कायम गर्छ।"}'::jsonb,true),
('dph-bmp-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',701,'{"question":"Which biomolecule is made of amino acids?","translation":"Amino acid बाट कुन biomolecule बनेको हुन्छ?","options":["Protein","Carbohydrate","Triglyceride","Nucleic acid"],"correctIndex":0,"explanation":"Proteins are polymers made from amino-acid building blocks.","explanationNe":"Protein amino acid नामका building block बाट बनेको polymer हो।"}'::jsonb,true),
('dph-bmp-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',702,'{"question":"Enzymes primarily function as:","translation":"Enzyme को मुख्य काम के हो?","options":["Biological catalysts","Genetic material","Cell walls","Energy stores only"],"correctIndex":0,"explanation":"Enzymes increase the rate of biochemical reactions without being consumed.","explanationNe":"Enzyme आफैँ खर्च नभई biochemical reaction को गति बढाउने biological catalyst हो।"}'::jsonb,true),
('dph-bmp-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',703,'{"question":"Which hormone generally lowers blood glucose?","translation":"कुन hormone ले सामान्यतया blood glucose घटाउँछ?","options":["Glucagon","Insulin","Adrenaline","Thyroxine"],"correctIndex":1,"explanation":"Insulin promotes glucose uptake and storage, lowering blood glucose.","explanationNe":"Insulin ले glucose uptake र storage बढाएर blood glucose घटाउँछ।"}'::jsonb,true),
('dph-bmp-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',704,'{"question":"Bacteria are generally classified as:","translation":"Bacteria लाई सामान्यतया कुन प्रकारको जीव मानिन्छ?","options":["Prokaryotes","Viruses","Fungi","Acellular particles"],"correctIndex":0,"explanation":"Bacteria are prokaryotic cells that lack a membrane-bound nucleus.","explanationNe":"Bacteria prokaryotic cell हुन् र membrane-bound nucleus हुँदैन।"}'::jsonb,true),
('dph-bmp-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',705,'{"question":"Viruses can replicate only:","translation":"Virus ले replication कहाँ गर्न सक्छ?","options":["In distilled water","Inside suitable host cells","On dry glass only","Without any host"],"correctIndex":1,"explanation":"Viruses depend on host-cell machinery for replication.","explanationNe":"Virus replication का लागि host cell को machinery मा निर्भर हुन्छ।"}'::jsonb,true),
('dph-bmp-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',706,'{"question":"Which process is intended to destroy all microbial life, including bacterial spores?","translation":"Bacterial spore सहित सबै microbial life नष्ट गर्ने प्रक्रिया कुन हो?","options":["Cleaning","Sterilization","Routine dusting","Hand washing only"],"correctIndex":1,"explanation":"A validated sterilization process is designed to eliminate all forms of microbial life, including spores.","explanationNe":"मान्य sterilization प्रक्रियाले spore सहित सबै प्रकारका microbial life हटाउने उद्देश्य राख्छ।"}'::jsonb,true),
('dph-bmp-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',707,'{"question":"Which statement best describes disinfection?","translation":"Disinfection को सही अर्थ कुन हो?","options":["Always destroys every bacterial spore","Reduces or eliminates many pathogenic microbes on objects","Is identical to sterilization","Is used only on living tissue"],"correctIndex":1,"explanation":"Disinfection reduces or eliminates many pathogens on inanimate objects but may not destroy spores.","explanationNe":"Disinfection ले निर्जीव वस्तुमा रहेका धेरै रोगकारक सूक्ष्मजीव घटाउँछ वा नष्ट गर्छ तर spore नष्ट नहुन सक्छ।"}'::jsonb,true),
('dph-bmp-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',708,'{"question":"The five commonly described cardinal signs of inflammation include:","translation":"Inflammation का पाँच सामान्य प्रमुख लक्षण कुन हुन्?","options":["Redness, heat, swelling, pain and loss of function","Cough, fever, rash, thirst and hunger","Pallor, jaundice, cyanosis, itching and sneezing","Only pain and fever"],"correctIndex":0,"explanation":"The classic signs are redness, heat, swelling, pain and loss of function.","explanationNe":"Inflammation का परम्परागत पाँच लक्षण redness, heat, swelling, pain र loss of function हुन्।"}'::jsonb,true),
('dph-bmp-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',709,'{"question":"Which specimen is commonly used to assess urinary glucose or protein?","translation":"Urine मा glucose वा protein जाँच्न कुन specimen प्रयोग हुन्छ?","options":["Urine","Hair","Nail clipping","Sputum only"],"correctIndex":0,"explanation":"Urine is the appropriate specimen for routine urinalysis, including glucose and protein testing.","explanationNe":"Glucose र protein लगायत routine urinalysis का लागि urine उपयुक्त specimen हो।"}'::jsonb,true),
('dph-bmp-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',710,'{"question":"Which action is essential before collecting a laboratory specimen?","translation":"Laboratory specimen संकलन गर्नुअघि कुन काम अनिवार्य छ?","options":["Leave the container unlabeled","Confirm patient identity and label correctly","Mix specimens from different patients","Ignore infection precautions"],"correctIndex":1,"explanation":"Correct patient identification and labeling prevent specimen mix-ups and diagnostic errors.","explanationNe":"सही बिरामी पहिचान र labeling ले specimen मिसिने तथा diagnosis गलत हुने जोखिम घटाउँछ।"}'::jsonb,true),
('dph-bmp-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',801,'{"question":"Name the four major classes of biomolecules and state one function of each.","answer":"Carbohydrates provide energy; lipids store energy and form membranes; proteins provide structure and perform catalytic and transport functions; nucleic acids store and transmit genetic information.","answerNe":"Carbohydrate ले ऊर्जा दिन्छ; lipid ले ऊर्जा सञ्चय र membrane निर्माण गर्छ; protein ले संरचना, catalysis र transport गर्छ; nucleic acid ले genetic information राख्छ र सार्छ।"}'::jsonb,true),
('dph-bmp-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',802,'{"question":"Differentiate sterilization and disinfection.","answer":"Sterilization eliminates all forms of microbial life, including spores, using a validated process. Disinfection reduces or eliminates many pathogenic microorganisms on inanimate objects but may not destroy spores.","answerNe":"Sterilization ले मान्य प्रक्रियाबाट spore सहित सबै microbial life हटाउँछ। Disinfection ले निर्जीव वस्तुमा रहेका धेरै रोगकारक सूक्ष्मजीव घटाउँछ वा नष्ट गर्छ तर spore नष्ट नहुन सक्छ।"}'::jsonb,true),
('dph-bmp-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',803,'{"question":"Explain the difference between bacteria and viruses.","answer":"Bacteria are living prokaryotic cells that can reproduce independently under suitable conditions. Viruses are acellular infectious agents that require host-cell machinery to replicate.","answerNe":"Bacteria उपयुक्त अवस्थामा आफैँ वृद्धि गर्न सक्ने prokaryotic cell हुन्। Virus कोशिकाविहीन infectious agent हो र replication का लागि host cell चाहिन्छ।"}'::jsonb,true),
('dph-bmp-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',804,'{"question":"List the five cardinal signs of inflammation and briefly explain their significance.","answer":"Redness, heat, swelling, pain and loss of function. They reflect vascular and cellular responses to tissue injury or infection.","answerNe":"Redness, heat, swelling, pain र loss of function inflammation का पाँच प्रमुख लक्षण हुन्। यी tissue injury वा infection प्रति vascular तथा cellular प्रतिक्रियाका संकेत हुन्।"}'::jsonb,true),
('dph-bmp-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',805,'{"question":"Mention four important precautions during collection and transport of a clinical specimen.","answer":"Confirm patient identity, use the correct sterile or appropriate container, label at the bedside/collection point, and transport promptly under recommended conditions while following infection-prevention precautions.","answerNe":"बिरामीको पहिचान पुष्टि गर्ने, सही sterile वा उपयुक्त container प्रयोग गर्ने, संकलनस्थलमै label गर्ने र संक्रमण रोकथामका सावधानी अपनाउँदै सिफारिस गरिएको अवस्थामा छिटो transport गर्ने।"}'::jsonb,true)
